"use client";

import { useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

type Side = "top" | "bottom";

export function Tooltip({ label, children }: { label: string; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [side, setSide] = useState<Side>("top");
  const anchorRef = useRef<HTMLSpanElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const showTooltip = () => {
    const rect = anchorRef.current?.getBoundingClientRect();
    if (rect) setSide(rect.top < 60 ? "bottom" : "top");
    setOpen(true);
  };

  return (
    <span
      ref={anchorRef}
      className="relative inline-flex"
      onMouseEnter={showTooltip}
      onMouseLeave={() => setOpen(false)}
      onFocus={showTooltip}
      onBlur={() => setOpen(false)}
    >
      {children}
      <AnimatePresence>
        {open && (
          <motion.span
            role="tooltip"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.9, y: side === "top" ? 4 : -4 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.92, y: side === "top" ? 4 : -4 }}
            transition={{ type: "spring", stiffness: 500, damping: 32 }}
            style={{ transformOrigin: side === "top" ? "bottom" : "top" }}
            className={`pointer-events-none absolute left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-slate-900 px-2.5 py-1.5 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900 ${
              side === "top" ? "-top-2 -translate-y-full" : "-bottom-2 translate-y-full"
            }`}
          >
            {label}
            <span
              aria-hidden
              className={`absolute left-1/2 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100 ${
                side === "top" ? "top-full -mt-1" : "bottom-full -mb-1"
              }`}
            />
          </motion.span>
        )}
      </AnimatePresence>
    </span>
  );
}
